-- Turn the two oversized official posters into compact editorial spotlights without transcribing official details.
SET @agent_old := '<h2>Agen Perubahan Pengadilan Negeri Natuna</h2><p><img src="images/zi/agen-perubahan.png" alt="Agen Perubahan Pengadilan Negeri Natuna" loading="lazy" decoding="async"></p>';
SET @agent_new := '<section class="zi-spotlight zi-spotlight--agent" aria-labelledby="zi-agent-title"><div class="zi-spotlight__poster"><img src="/images/zi/agen-perubahan.png" alt="Poster resmi Agen Perubahan Pengadilan Negeri Natuna periode 2026" loading="lazy" decoding="async"></div><div class="zi-spotlight__copy"><span class="zi-spotlight__mark" aria-hidden="true">ZI</span><p class="zi-spotlight__eyebrow">Penetapan resmi satuan kerja</p><h2 id="zi-agent-title">Agen Perubahan</h2><p>Figur penggerak budaya kerja yang mendorong integritas, inovasi, dan perubahan nyata di lingkungan Pengadilan Negeri Natuna.</p><ul><li>Penggerak nilai integritas</li><li>Pendorong inovasi layanan</li><li>Teladan perubahan berkelanjutan</li></ul><a href="/images/zi/agen-perubahan.png" target="_blank" rel="noopener">Buka poster penuh <span aria-hidden="true">↗</span></a></div></section>';
SET @role_old := '<h2>Role Model Pengadilan Negeri Natuna</h2><p><img src="images/zi/role-model.png" alt="Role Model Pengadilan Negeri Natuna" loading="lazy" decoding="async"></p>';
SET @role_new := '<section class="zi-spotlight zi-spotlight--role" aria-labelledby="zi-role-title"><div class="zi-spotlight__poster"><img src="/images/zi/role-model.png" alt="Poster resmi Role Model Pengadilan Negeri Natuna tahun 2026" loading="lazy" decoding="async"></div><div class="zi-spotlight__copy"><span class="zi-spotlight__mark" aria-hidden="true">ZI</span><p class="zi-spotlight__eyebrow">Keteladanan resmi satuan kerja</p><h2 id="zi-role-title">Role Model</h2><p>Figur teladan yang menghadirkan nilai integritas, profesionalitas, dan pelayanan melalui tindakan sehari-hari.</p><ul><li>Konsisten menjaga integritas</li><li>Profesional dalam pelaksanaan tugas</li><li>Memberi teladan pelayanan</li></ul><a href="/images/zi/role-model.png" target="_blank" rel="noopener">Buka poster penuh <span aria-hidden="true">↗</span></a></div></section>';
UPDATE #__content SET introtext=REPLACE(introtext,@agent_old,@agent_new),modified=UTC_TIMESTAMP() WHERE id=(SELECT article_id FROM (SELECT CAST(SUBSTRING_INDEX(link,'id=',-1) AS UNSIGNED) article_id FROM #__menu WHERE menutype='mainmenu' AND path='zona-integritas/agen-perubahan' AND published=1 ORDER BY id LIMIT 1) linked) AND introtext LIKE CONCAT('%',@agent_old,'%');
UPDATE #__content SET introtext=REPLACE(introtext,@role_old,@role_new),modified=UTC_TIMESTAMP() WHERE id=(SELECT article_id FROM (SELECT CAST(SUBSTRING_INDEX(link,'id=',-1) AS UNSIGNED) article_id FROM #__menu WHERE menutype='mainmenu' AND path='zona-integritas/role-model' AND published=1 ORDER BY id LIMIT 1) linked) AND introtext LIKE CONCAT('%',@role_old,'%');
